CREATE TABLE IF NOT EXISTS users (id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL,email VARCHAR(150) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('student','mentor','admin') NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS profiles (user_id INT PRIMARY KEY,bio TEXT,organization VARCHAR(150),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS skills (id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(80) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS user_skills (user_id INT NOT NULL,skill_id INT NOT NULL,level INT NOT NULL CHECK(level BETWEEN 1 AND 4),PRIMARY KEY(user_id,skill_id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(skill_id) REFERENCES skills(id));
CREATE TABLE IF NOT EXISTS companies (id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(150) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS internships (id INT PRIMARY KEY AUTO_INCREMENT,company_id INT NOT NULL,title VARCHAR(150) NOT NULL,description TEXT NOT NULL,location VARCHAR(100) NOT NULL,stipend DECIMAL(10,2) NOT NULL CHECK(stipend>=0),deadline DATETIME NOT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(company_id) REFERENCES companies(id));
CREATE TABLE IF NOT EXISTS internship_skills (internship_id INT NOT NULL,skill_id INT NOT NULL,importance ENUM('critical','required','preferred') NOT NULL,min_level INT NOT NULL CHECK(min_level BETWEEN 1 AND 4),PRIMARY KEY(internship_id,skill_id),FOREIGN KEY(internship_id) REFERENCES internships(id),FOREIGN KEY(skill_id) REFERENCES skills(id));
CREATE TABLE IF NOT EXISTS applications (id INT PRIMARY KEY AUTO_INCREMENT,student_id INT NOT NULL,internship_id INT NOT NULL,status ENUM('applied','shortlisted','selected','rejected','withdrawn') NOT NULL DEFAULT 'applied',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(student_id,internship_id),FOREIGN KEY(student_id) REFERENCES users(id),FOREIGN KEY(internship_id) REFERENCES internships(id));
CREATE TABLE IF NOT EXISTS application_status_history (id INT PRIMARY KEY AUTO_INCREMENT,application_id INT NOT NULL,status VARCHAR(20) NOT NULL,actor_id INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(application_id) REFERENCES applications(id),FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS mentorships (id INT PRIMARY KEY AUTO_INCREMENT,student_id INT NOT NULL,mentor_id INT NOT NULL,status ENUM('pending','accepted','declined','closed') NOT NULL DEFAULT 'pending',UNIQUE(student_id,mentor_id),FOREIGN KEY(student_id) REFERENCES users(id),FOREIGN KEY(mentor_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS mentor_slots (id INT PRIMARY KEY AUTO_INCREMENT,mentor_id INT NOT NULL,starts_at DATETIME NOT NULL,ends_at DATETIME NOT NULL,CHECK(ends_at>starts_at),INDEX(mentor_id,starts_at),FOREIGN KEY(mentor_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS mentorship_sessions (id INT PRIMARY KEY AUTO_INCREMENT,mentorship_id INT NOT NULL,slot_id INT UNIQUE NOT NULL,FOREIGN KEY(mentorship_id) REFERENCES mentorships(id),FOREIGN KEY(slot_id) REFERENCES mentor_slots(id));
CREATE TABLE IF NOT EXISTS auth_sessions (token_hash CHAR(64) PRIMARY KEY,user_id INT NOT NULL,expires_at DATETIME NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE OR REPLACE VIEW open_internships AS SELECT i.*,c.name company FROM internships i JOIN companies c ON c.id=i.company_id WHERE i.is_active=TRUE AND i.deadline>UTC_TIMESTAMP();
